public class LogParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("parseLevel INFO line", "INFO", LogParser.parseLevel("[INFO] server started"));
        check("parseLevel ERROR line", "ERROR", LogParser.parseLevel("[ERROR] disk full"));
        check("parseLevel plain text", "", LogParser.parseLevel("no brackets here"));
        check("parseLevel lowercase level rejected", "", LogParser.parseLevel("[warn] lowercase"));
        check("parseLevel empty message", "DEBUG", LogParser.parseLevel("[DEBUG] "));
        String[] lines = {
                "[ERROR] out of memory",
                "[INFO] retrying",
                "[ERROR] out of disk",
                "just noise",
                "[WARNING] almost full"
        };
        check("countErrors mixed lines", 2, LogParser.countErrors(lines));
        check("countErrors empty array", 0, LogParser.countErrors(new String[0]));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

