public class LogParser {

    private static final java.util.regex.Pattern LINE =
            java.util.regex.Pattern.compile("\\[([A-Z]+)\\] .*");

    public static String parseLevel(String line) {
        java.util.regex.Matcher m = LINE.matcher(line);
        if (m.matches()) {
            return m.group(1);
        }
        return "";
    }

    public static int countErrors(String[] lines) {
        int count = 0;
        for (String line : lines) {
            if (parseLevel(line).equals("ERROR")) {
                count++;
            }
        }
        return count;
    }
}
